// План specs/billing-granted-plan.md, 2.3. Каждый назначенный тариф: текст без trial; «Add Payment Method» — только Starter Tech и Pro Tech.
// ПИШЕТ данные на проде: только «בדיקה», revokeIfAssigned до и в finally. Не @prod-safe.
import { test, expect } from '../../fixtures';
import { setLanguage, revokeIfAssigned, enDate } from '../admin-plans/plans-helpers';
import { REASON, UNTIL_DAYS, PROPAGATION_MS, grantedTextEn, addPaymentButton, assignPlan, changePlan } from './granted-helpers';

test.describe.configure({ mode: 'serial' });

// Наличие кнопки по тарифам — фактическое поведение, принятое на QA 07.10 (скрины 03, 05, 05b, 06).
const PLANS: { name: string; cardButton: boolean }[] = [
  { name: 'Starter Tech', cardButton: true },
  { name: 'Pro Tech', cardButton: true },
  { name: 'Growth Company', cardButton: false },
  { name: 'Scale Enterprise', cardButton: false },
];

test.describe('Billing — granted plan seen by the user', () => {
  test('For every granted plan the payment text has no trial wording; Add Payment Method only on Starter Tech and Pro Tech #550e01db @desktop @writes', async ({ asUser }) => {
    test.setTimeout(900_000);
    const admin = await asUser('admin');
    const user = await asUser('user');
    await setLanguage(admin, 'en');
    await setLanguage(user, 'en');

    await revokeIfAssigned(admin, `${REASON} pre-clean`);

    const date = enDate(UNTIL_DAYS);
    try {
      for (const [i, plan] of PLANS.entries()) {
        await test.step(plan.name, async () => {
          if (i === 0) await assignPlan(admin, plan.name);
          else await changePlan(admin, plan.name);

          await user.goto('/BillingSubscription');
          // Ждём, пока до пользователя дойдёт именно этот тариф: строка таблицы подписки
          // с названием тарифа и бейджем «Granted by Techory until <date>».
          const badge = user.getByText(`Granted by Techory until ${date}`, { exact: true });
          const planRow = user.getByRole('row').filter({ hasText: plan.name }).filter({ has: badge });
          await expect(async () => {
            await user.reload();
            await expect(planRow).toBeVisible({ timeout: 10_000 });
          }).toPass({ timeout: PROPAGATION_MS });

          const granted = user.getByText(grantedTextEn(date));
          await expect(granted).toBeVisible();
          await expect(user.getByText(/after the trial/i)).toHaveCount(0);
          await expect(granted.locator('xpath=..')).not.toContainText(/trial/i);
          if (plan.cardButton) await expect(addPaymentButton(user).first()).toBeVisible();
          else await expect(addPaymentButton(user)).toHaveCount(0);
        });
      }
    } finally {
      await revokeIfAssigned(admin, `${REASON} cleanup`);
    }
  });
});
